export interface AssetDiente {
  /** Medidas del dibujo original, para respetar su proporcion. */
  ancho: number;
  alto: number;
  /** A que altura del dibujo pasa la linea de la encia. */
  cuello: number;
  /** La silueta de la pieza, para recortar cosas contra ella. */
  contorno: string;
  /** Cada capa por separado: "tooth", "caries-mesial", "zircon"... */
  capas: Record<string, string>;
}

